import os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
FIX = os.path.join(HERE, "fixtures") + os.sep
sys.path.insert(0, HERE)
import re
from shots import run, BASE, OUT

# The second round of invoicing, 18 Nov 2026: the aged-debt squares as filters, the Back button
# on every screen, the Sage export as one list with sales and purchases, supplier invoices
# approved (accounts to the limit, the managing director above) and then paid, the confirm box
# on every approval and payment, subcontractors in their own section of the portal sending
# invoices that a site manager approves, and the paid notice in both portals.

results = []
def check(name, cond, detail=""):
    results.append((name, bool(cond), str(detail)))
def data(page, expr):
    return page.evaluate("(() => { const s = JSON.parse(localStorage.getItem('cod.data')).state; const db = s.db; const day = s.day; const stage = (x) => x.readStatus === 'not_read' ? 'unread' : x.readStatus !== 'confirmed' ? (x.askedAt ? 'approve' : x.sentBack ? 'back' : 'check') : x.docType === 'credit_note' ? 'credit' : x.paidOn ? 'paid' : 'pay'; return " + expr + "; })()")
def as_role(page, role):
    page.get_by_role("button", name="Account menu").click()
    page.get_by_role("menuitem", name=role).click()
    page.wait_for_timeout(350)
def go(page, path, sel="main"):
    page.goto(BASE + path); page.wait_for_selector(sel); page.wait_for_timeout(250)

def steps(page, ctx):
    page.goto(BASE + "/"); page.wait_for_url("**/sign-in")
    page.fill("#username", "demo"); page.fill("#password", "demo"); page.click("button[type=submit]")
    page.wait_for_url("**/who"); page.get_by_role("button", name="Managing director").click(); page.wait_for_url("**/dashboard")
    page.wait_for_selector("main"); page.wait_for_timeout(300)
    main = page.locator("main")
    dlg = lambda: page.locator("dialog[open]").last
    back = page.get_by_role("button", name="Back", exact=True)
    bar = page.get_by_role("navigation", name="Departments")
    toast = lambda: page.locator("body").inner_text()

    # ── The Back button
    check("Back: it is at the far left of the top bar, before the firm's name", back.count() == 1 and back.bounding_box()["x"] < page.get_by_role("link", name=re.compile("home$")).bounding_box()["x"] and back.bounding_box()["y"] < 50)
    check("Back: on the first screen after signing in there is nowhere to go back to", back.is_disabled())
    bar.get_by_role("link", name="Invoicing").click(); page.wait_for_url("**/invoicing"); page.wait_for_selector("table")
    check("Back: it wakes up once a second screen has been opened", back.is_enabled())
    first = page.locator("tbody tr a").first.inner_text()
    page.locator("tbody tr a").first.click(); page.wait_for_url(f"**/invoicing/client/{first}")
    bar.get_by_role("link", name="Projects").click(); page.wait_for_url("**/projects")
    back.click(); page.wait_for_url(f"**/invoicing/client/{first}")
    check("Back: from another department it returns to the invoice that was open", page.url.endswith(f"/invoicing/client/{first}") and main.get_by_role("heading", name=first).count() >= 1)
    page.reload(); page.wait_for_selector("main"); page.wait_for_timeout(300)
    check("Back: a reload does not forget the way here", back.is_enabled())
    back.click(); page.wait_for_url("**/invoicing"); page.wait_for_timeout(200)
    back.click(); page.wait_for_url("**/dashboard"); page.wait_for_timeout(200)
    check("Back: all the way to the first screen, where it stops", page.url.endswith("/dashboard") and back.is_disabled())
    # Merged 19 Nov: Back keeps its own trail (the other copy's, with filters and height), so it opens the screen again rather than using the browser's history.
    bar.get_by_role("link", name="Invoicing").click(); page.wait_for_url("**/invoicing"); page.wait_for_timeout(200)
    check("Back: it wakes up again on the next screen opened", back.is_enabled())
    seen = []
    for name, url in [("Email", "**/inbox"), ("Sales", "**/sales"), ("Schedule", "**/schedule"), ("People", "**/people/timesheet"), ("Plant", "**/plant"), ("Fleet", "**/fleet"), ("Compliance", "**/compliance"), ("Portal", "**/portal"), ("Site phone", "**/site"), ("Admin", "**/admin**")]:
        bar.get_by_role("link", name=re.compile(rf"(^|\s){re.escape(name)}$")).click(); page.wait_for_url(url); page.wait_for_timeout(150)
        seen.append(back.count() == 1 and back.is_enabled())
    check("Back: it is on every department's screens, the portal and the site phone included", all(seen), seen)
    page.get_by_role("button", name="Account menu").click(); page.get_by_role("menuitem", name="Settings").click(); page.wait_for_url("**/settings"); page.wait_for_timeout(200)
    back.click(); page.wait_for_url("**/admin**")
    check("Back: and on Settings, from where it returns to Admin", "/admin" in page.url)
    as_role(page, "Accounts")
    check("Back: after changing role it starts again, so it cannot lead into the role before", "/invoicing" in page.url and back.is_disabled())
    as_role(page, "Managing director")

    # A reset writes the sample data to the browser's storage, where data() reads it from.
    page.get_by_role("button", name="Account menu").click(); page.get_by_role("menuitem", name="Reset demo data").click()
    page.get_by_role("button", name="Reset demo data").click(); page.wait_for_timeout(300)

    # ── The squares over the client invoices
    go(page, "/invoicing", "table")
    strip = page.get_by_role("navigation", name="Aged debt")
    tabs = page.get_by_role("tablist", name="Invoices shown")
    n = data(page, "(() => { const late = (i) => Math.round((Date.parse(day) - Date.parse(i.dueOn)) / 864e5); const out = db.salesInvoices.filter(i => i.status === 'Invoiced'); return { all: db.salesInvoices.length, out: out.length, current: out.filter(i => late(i) <= 0).length, b1: out.filter(i => late(i) > 0 && late(i) <= 30).length, b2: out.filter(i => late(i) > 30 && late(i) <= 60).length } })()")
    check("Squares: five of them, each one a link", strip.get_by_role("link").count() == 5 and page.locator("tbody tr").count() == n["all"])
    strip.get_by_role("link", name=re.compile("^1 to 30 days late")).click(); page.wait_for_timeout(300)
    check("Squares: 1 to 30 days late shows just those invoices, and the square stays pressed", "age=1" in page.url and page.locator("tbody tr").count() == n["b1"] and n["b1"] > 0 and all("days late" in r.inner_text() for r in page.locator("tbody tr").all()) and strip.get_by_role("link", name=re.compile("^1 to 30 days late")).get_attribute("aria-current") == "true" and tabs.get_by_role("tab", name=re.compile("^Sent")).get_attribute("aria-selected") == "true", (page.url, n))
    page.screenshot(path=f"{OUT}/220-age-filter.png")
    strip.get_by_role("link", name=re.compile("^Not yet due")).click(); page.wait_for_timeout(300)
    check("Squares: Not yet due shows what is sent and still inside its terms", "age=0" in page.url and page.locator("tbody tr").count() == n["current"] and not any("days late" in r.inner_text() for r in page.locator("tbody tr").all()))
    strip.get_by_role("link", name=re.compile("^31 to 60 days late")).click(); page.wait_for_timeout(300)
    check("Squares: an empty band says so in plain words", n["b2"] == 0 and "No invoice is 31 to 60 days late" in main.inner_text())
    strip.get_by_role("link", name=re.compile("^Owed to us")).click(); page.wait_for_timeout(300)
    check("Squares: Owed to us shows everything sent and unpaid", page.url.endswith("/invoicing/invoiced") and page.locator("tbody tr").count() == n["out"] and strip.get_by_role("link", name=re.compile("^Owed to us")).get_attribute("aria-current") == "true")
    strip.get_by_role("link", name=re.compile("^1 to 30 days late")).click(); page.wait_for_timeout(200)
    strip.get_by_role("link", name=re.compile("^1 to 30 days late")).click(); page.wait_for_timeout(300)
    check("Squares: pressing the same square again lets go of it", page.url.endswith("/invoicing/invoiced") and page.locator("tbody tr").count() == n["out"])

    # ── Sage: one name, one list, sales and purchases
    go(page, "/invoicing/export", "table")
    side = page.get_by_role("navigation", name="Invoicing screens").first
    check("Sage: the sidebar and the page say Sage, never Sage 50, Xero or a spreadsheet", side.get_by_role("link", name=re.compile("^Sage export")).count() == 1 and main.get_by_role("heading", name="Sage export").count() == 1 and not re.search(r"Sage 50|Xero|Spreadsheet", page.locator("body").inner_text()))
    check("Sage: Download CSV sits over the table, with the nominal codes named beside it", main.get_by_role("button", name="Download CSV").count() == 1 and "Sales day book, one row per invoice, nominal codes 4000 Contract works, 4010 Agreed extras" in main.inner_text())
    page.screenshot(path=f"{OUT}/221-sage-sales.png")
    page.get_by_role("tablist", name="Day book").get_by_role("tab", name=re.compile("^Purchases")).click(); page.wait_for_timeout(300)
    book = main.get_by_label("What Sage receives, purchases")
    head = [h.inner_text() for h in book.locator("thead th").all()]
    rows = [[c.inner_text() for c in r.locator("td").all()] for r in book.locator("tbody tr").all()]
    want = data(page, "(() => { const ok = db.supplierInvoices.filter(s => s.readStatus === 'confirmed'); return { lines: ok.reduce((t, s) => t + s.allocations.length, 0), newInvoices: ok.filter(s => !s.exportedAt).length, newLines: ok.filter(s => !s.exportedAt).reduce((t, s) => t + s.allocations.length, 0) } })()")
    check("Sage purchases: a row for each line of each approved invoice, with the file number as the extra reference", head == ["Type", "Account", "Nominal", "Dept", "Date", "Ref", "Details", "Net", "Tax", "VAT", "Ex ref", "In Sage"] and len(rows) == want["lines"] and all(r[0] in ("PI", "PC") and re.match(r"^\d{4}$", r[2]) and re.match(r"^\d{3}$", r[3]) and re.match(r"^F-\d{4}$", r[10]) for r in rows) and [r[11] for r in rows].count("Not yet") == want["newLines"], (head, len(rows), want))
    check("Sage purchases: a subcontractor goes to nominal 6002 at the building rate, materials to 5000 at the standard rate", any(r[1] == "KINSTO" and r[2] == "6002" and r[8] == "T3" for r in rows) and any(r[1] == "BURLIM" and r[2] == "5000" and r[8] == "T1" for r in rows) and any(r[0] == "PC" for r in rows))
    page.screenshot(path=f"{OUT}/222-sage-purchases.png")
    with page.expect_download() as dl:
        main.get_by_role("button", name="Download CSV").click()
    text = open(dl.value.path(), encoding="utf-8", newline="").read()
    check("Sage purchases: the file holds only what Sage did not have, with no heading row", re.match(r"purchase-invoices-sage-\d{4}-\d\d-\d\d\.csv", dl.value.suggested_filename) and text.count("\r\n") == want["newLines"] and text.startswith("PI,") and "Type," not in text, (dl.value.suggested_filename, text.count("\r\n"), want))
    page.wait_for_timeout(300)
    check("Sage purchases: afterwards nothing is left to send, and the file is kept under Earlier files", main.get_by_role("button", name="Download CSV").is_disabled() and data(page, "db.supplierInvoices.filter(s => s.readStatus === 'confirmed' && !s.exportedAt).length") == 0 and f"{want['newInvoices']} invoices" in main.get_by_label("Earlier files").locator("tbody tr").first.inner_text())
    go(page, "/settings/region")
    check("Settings: the choice of accounts package is gone", "Accounts package" not in main.inner_text() and page.get_by_role("tab", name="Xero").count() == 0)
    page.get_by_role("button", name="Account menu").click(); page.get_by_role("menuitem", name="Reset demo data").click()
    page.get_by_role("button", name="Reset demo data").click(); page.wait_for_timeout(300)

    # ── Supplier invoices: accounts check, the limit decides who approves
    as_role(page, "Accounts")
    go(page, "/invoicing/supplier")
    q = page.get_by_role("list", name="Supplier invoices")
    check("Supplier invoices: listed by where each stands, accounts' own first", [p.inner_text().split(" (")[0] for p in q.locator("li > p").all()] == ["With accounts", "Waiting for approval", "To be paid", "Paid, newest first"] and "4 to deal with, 2 waiting for approval" in main.inner_text(), [p.inner_text() for p in q.locator("li > p").all()])
    q.get_by_role("button", name=re.compile("BLS-20417")).click(); page.wait_for_timeout(300)
    check("Accounts: an invoice over 500 before VAT cannot be approved by them, only sent on", main.get_by_role("button", name="Approve to job costs").count() == 0 and main.get_by_role("button", name="Send for approval").is_enabled() and "is over the €500 that accounts may approve, so the managing director approves it" in main.inner_text())
    main.get_by_role("button", name="Send for approval").click(); page.wait_for_timeout(300)
    check("Accounts: sent for approval, it waits for the managing director and is out of their own list", data(page, "stage(db.supplierInvoices.find(s => s.invoiceNo === 'BLS-20417'))") == "approve" and "Waiting for the managing director" in main.inner_text() and "3 to deal with, 3 waiting for approval" in main.inner_text() and main.get_by_role("button", name="Take it back to change").count() == 1)
    q.get_by_role("button", name=re.compile("LSW-30087")).click(); page.wait_for_timeout(300)
    main.get_by_role("button", name="Read this invoice").click(); page.wait_for_timeout(300)
    check("Accounts: one within the limit they may approve themselves", main.get_by_role("button", name="Approve to job costs").is_enabled() and "is within the €500 that accounts may approve" in main.inner_text())
    main.get_by_role("button", name="Approve to job costs").click(); page.wait_for_timeout(300)
    check("Approve: a box asks first, saying where it goes", dlg().get_by_role("heading", name="Approve this invoice?").count() == 1 and "It goes into the job costs of C723" in dlg().inner_text() and data(page, "stage(db.supplierInvoices.find(s => s.invoiceNo === 'LSW-30087'))") == "check")
    dlg().get_by_role("button", name="Cancel").click(); page.wait_for_timeout(250)
    check("Approve: Cancel leaves it as it was", data(page, "stage(db.supplierInvoices.find(s => s.invoiceNo === 'LSW-30087'))") == "check")
    main.get_by_role("button", name="Approve to job costs").click(); page.wait_for_timeout(250)
    dlg().get_by_role("button", name="Confirm approval").click(); page.wait_for_timeout(300)
    check("Approve: Confirm approval puts it in job costs and passes it to be paid", data(page, "(() => { const s = db.supplierInvoices.find(s => s.invoiceNo === 'LSW-30087'); return [stage(s), s.confirmedBy] })()") == ["pay", "Maeve Quirke"] and main.get_by_role("button", name="Mark paid").count() == 1)
    go(page, "/invoicing/approve", "table")
    check("To approve, as accounts: they see what is waiting and for whom, with nothing to press", page.locator("tbody tr").count() == 7 and page.get_by_role("button", name=re.compile("^Approve")).count() == 0 and "None of them is yours to approve" in main.inner_text() and "Róisín Garvey or the managing director" in main.inner_text() and main.get_by_role("button", name=re.compile("limit")).count() == 0)

    # ── The managing director approves, sends back and sets the limit
    as_role(page, "Managing director")
    go(page, "/invoicing/approve", "table")
    check("To approve, as the managing director: every one is theirs, suppliers and subcontractors", page.locator("tbody tr").count() == 7 and page.get_by_role("button", name=re.compile("^Approve ")).count() == 7 and "7 of them are yours to approve" in main.inner_text())
    page.get_by_role("tablist", name="Invoices to approve").get_by_role("tab", name=re.compile("^Suppliers")).click(); page.wait_for_timeout(250)
    check("To approve: narrowed to suppliers", page.locator("tbody tr").count() == 3 and all("Supplier" in r.inner_text() for r in page.locator("tbody tr").all()))
    page.screenshot(path=f"{OUT}/223-to-approve.png")
    c725 = "db.supplierInvoices.filter(s => s.readStatus === 'confirmed').flatMap(s => s.allocations).filter(a => a.projectId === 'pr-C725' && a.category === 'material').reduce((t, a) => t + a.amount, 0)"
    before = data(page, c725)
    page.get_by_role("button", name="Approve SBS-7755").click(); page.wait_for_timeout(250)
    check("Approve from the list: the same box, with the amount and the site", "Slieve Bloom Sawmills" in dlg().inner_text() and "€2,870.82" in dlg().inner_text() and "C725 Granary Quay Warehouses" in dlg().inner_text())
    dlg().get_by_role("button", name="Confirm approval").click(); page.wait_for_timeout(300)
    check("Approve from the list: it leaves the list and lands in C725's material costs", page.locator("tbody tr").count() == 2 and round(data(page, c725) - before, 2) == 2334 and data(page, "db.supplierInvoices.find(s => s.invoiceNo === 'SBS-7755').confirmedBy") == "Aidan King")
    page.get_by_role("button", name="Send back ALC-6631").click(); page.wait_for_timeout(250)
    check("Send back: it needs a reason", dlg().get_by_role("button", name="Send it back").is_disabled())
    dlg().get_by_label("What is wrong with it").fill("Four rolls invoiced, three delivered to site."); dlg().get_by_role("button", name="Send it back").click(); page.wait_for_timeout(300)
    go(page, "/invoicing/supplier?inv=si-p2")
    check("Send back: it is back with accounts, with the reason on it", data(page, "stage(db.supplierInvoices.find(s => s.invoiceNo === 'ALC-6631'))") == "back" and "Sent back by Aidan King" in main.inner_text() and "Four rolls invoiced, three delivered to site." in main.inner_text())
    go(page, "/invoicing/approve", "table")
    main.get_by_role("button", name="Change the €500 limit").click(); page.wait_for_timeout(250)
    box = dlg().get_by_label("Limit before VAT"); box.click(); box.press("ControlOrMeta+a"); page.keyboard.type("3000", delay=30)
    dlg().get_by_role("button", name="Save the limit").click(); page.wait_for_timeout(300)
    check("The limit: the managing director can change what accounts may approve", data(page, "db.approvalLimits[0].amount") == 3000 and "up to €3,000 before VAT" in main.inner_text())
    as_role(page, "Accounts")
    go(page, "/invoicing/approve", "table")
    check("The limit: accounts can now approve the supplier invoice that was waiting, and still no subcontractor's", page.get_by_role("button", name="Approve BLS-20417").count() == 1 and page.get_by_role("button", name=re.compile("^Approve ")).count() == 1)

    # ── To be paid: accounts pay and mark paid, with a confirm box and an undo
    go(page, "/invoicing/to-pay", "table")
    owed = data(page, "(() => { const l = db.supplierInvoices.filter(s => stage(s) === 'pay'); return { n: l.length, late: l.filter(s => s.dueOn < day).length, paid: db.supplierInvoices.filter(s => stage(s) === 'paid').length } })()")
    check("To be paid: every approved invoice, soonest first, the late ones marked", page.locator("tbody tr").count() == owed["n"] and f"{owed['n']} approved invoices to pay" in main.inner_text() and sum(1 for r in page.locator("tbody tr").all() if "days late" in r.inner_text() or "day late" in r.inner_text()) == owed["late"] == 2 and "late" in page.locator("tbody tr").first.inner_text(), owed)
    check("To be paid: the two just approved are here", "SBS-7755" in main.inner_text() and "LSW-30087" in main.inner_text())
    page.screenshot(path=f"{OUT}/224-to-pay.png")
    main.get_by_role("searchbox").fill("sbs-7755"); page.wait_for_timeout(250)
    check("To be paid: the search finds one by its number", page.locator("tbody tr").count() == 1)
    page.get_by_role("button", name="Mark SBS-7755 paid").click(); page.wait_for_timeout(250)
    check("Mark paid: a box asks first, with the day and a reference; a supplier has no portal to be told in", dlg().get_by_role("heading", name="Mark this invoice as paid?").count() == 1 and dlg().get_by_label("Paid on").input_value() == data(page, "day") and dlg().get_by_role("checkbox").count() == 0 and "stay in Sage" in dlg().inner_text())
    dlg().get_by_role("button", name="Cancel").click(); page.wait_for_timeout(250)
    check("Mark paid: Cancel pays nothing", data(page, "stage(db.supplierInvoices.find(s => s.invoiceNo === 'SBS-7755'))") == "pay")
    page.get_by_role("button", name="Mark SBS-7755 paid").click(); page.wait_for_timeout(250)
    dlg().get_by_label("Payment reference").fill("BT 4471"); dlg().get_by_role("button", name="Confirm paid").click(); page.wait_for_timeout(300)
    check("Mark paid: Confirm paid records it, and the message offers Undo", data(page, "(() => { const s = db.supplierInvoices.find(s => s.invoiceNo === 'SBS-7755'); return [stage(s), s.paidOn === day, s.paidRef, s.paidBy] })()") == ["paid", True, "BT 4471", "Maeve Quirke"] and page.get_by_role("button", name="Undo", exact=True).count() == 1)
    page.get_by_role("button", name="Undo", exact=True).click(); page.wait_for_timeout(300)
    check("Undo: it is waiting to be paid again", data(page, "stage(db.supplierInvoices.find(s => s.invoiceNo === 'SBS-7755'))") == "pay")
    main.get_by_role("searchbox").fill("")
    page.get_by_role("tablist", name="Invoices shown").get_by_role("tab", name=re.compile("^Paid")).click(); page.wait_for_timeout(300)
    check("Paid: what has been paid, newest first, each with Undo paid", page.locator("tbody tr").count() == owed["paid"] and page.get_by_role("button", name=re.compile("^Undo paid")).count() == owed["paid"] and "Pay run" in page.locator("tbody tr").first.inner_text())
    page.get_by_role("button", name=re.compile("^Undo paid")).first.click(); page.wait_for_timeout(300)
    check("Paid: Undo paid puts one back to be paid", data(page, "db.supplierInvoices.filter(s => stage(s) === 'paid').length") == owed["paid"] - 1)

    # ── The portal in two sections, and subcontractors kept apart on a shared site
    as_role(page, "Managing director")
    go(page, "/portal")
    pside = page.get_by_role("navigation", name="Portal screens").first
    check("Portal: two sections in the sidebar, clients and subcontractors", all(w in pside.inner_text() for w in ["Clients", "What a client sees", "Subcontractors", "What a subcontractor sees"]))
    pside.get_by_role("link", name=re.compile("^What a subcontractor sees")).click(); page.wait_for_url("**/portal/subcontractors"); page.wait_for_timeout(300)
    pick = page.get_by_role("list", name="Subcontractors by site")
    by_site = {p.inner_text(): [b.get_attribute("aria-label") for b in li.get_by_role("button").all()] for li in pick.locator("> li").all() for p in [li.locator("> p")]}
    check("Subcontractor portal: the list on the left has each site with its subcontractors one under the other", list(by_site.keys()) == ["C719 St Finian's Church", "C720 Ardmullen House", "C721 The Old Corn Mill", "C722 Dunmoy Courthouse"] and by_site["C719 St Finian's Church"] == ["Corrib Scaffolding at C719", "Curragh Electrical Services at C719", "Kinvara Stone Carvers at C719"] and by_site["C721 The Old Corn Mill"] == ["Corrib Scaffolding at C721", "Lahinch Roofing and Leadwork at C721"], by_site)
    view = lambda: page.get_by_label(re.compile("^What .* sees$"))
    pick.get_by_role("button", name="Lahinch Roofing and Leadwork at C721").click(); page.wait_for_timeout(300)
    t = view().inner_text()
    check("Subcontractor portal: one subcontractor sees their own invoices on a shared site and nothing of the other's", main.get_by_role("heading", name="Lahinch Roofing and Leadwork").count() == 1 and "LRL-0412" in t and "CS-INV" not in t and "Corrib" not in t and "This is exactly what Orla Considine of Lahinch Roofing and Leadwork sees" in t)
    check("Subcontractor portal: nothing internal is shown", not re.search(r"margin|job costs|cost to date|hourly|nominal|file number|F-1\d\d\d", t, re.I))
    pick.get_by_role("button", name="Kinvara Stone Carvers at C722").click(); page.wait_for_timeout(300)
    check("Subcontractor portal: an invoice sent back shows with the site manager's reason", "Sent back: invoice KSC-325 for C722." in view().inner_text() and "Nine stones are invoiced but seven have reached site" in view().inner_text())
    pick.get_by_role("button", name="Corrib Scaffolding at C721").click(); page.wait_for_timeout(300)
    news = page.get_by_role("list", name="News on your invoices")
    check("Subcontractor portal: a payment made in the last month is announced at the top", news.count() == 1 and re.search(r"Paid: invoice CS-INV-\d+ for C\d+\. €[\d,]+\.\d\d was paid on \d+ \w+ 2026", news.inner_text()), news.inner_text() if news.count() else "")
    glance = page.get_by_label("Your invoices at a glance").inner_text()
    check("Subcontractor portal: what is waiting, approved and paid, at a glance", all(w in glance for w in ["Waiting for approval", "Approved, to be paid", "Paid in the last 30 days"]))
    check("Subcontractor portal: the site picked on the left comes first", view().locator("section[aria-label^='C']").first.get_attribute("aria-label") == "C721 The Old Corn Mill")
    page.screenshot(path=f"{OUT}/225-sub-portal.png", full_page=True)

    # ── A subcontractor sends an invoice
    view().get_by_role("button", name="Send an invoice for C721").click(); page.wait_for_timeout(300)
    d = dlg()
    check("Send an invoice: the site is the one it was opened from, and it cannot go empty", d.get_by_label("Site").input_value() == "pr-C721" and d.get_by_role("button", name="Send invoice").is_disabled() and [o.inner_text() for o in d.get_by_label("Site").locator("option").all()] == ["C721 The Old Corn Mill", "C719 St Finian's Church"], [o.inner_text() for o in d.get_by_label("Site").locator("option").all()])
    d.get_by_label("Your invoice number").fill("CS-INV-9914"); d.get_by_label("What it is for").fill("Scaffold strike, east gable"); page.wait_for_timeout(200)
    check("Send an invoice: a number already used is refused", "You have already sent CS-INV-9914" in d.inner_text() and d.get_by_role("button", name="Send invoice").is_disabled())
    d.get_by_label("Your invoice number").fill("CS-INV-9930")
    amt = d.get_by_label("Amount before VAT"); amt.click(); amt.press("ControlOrMeta+a"); page.keyboard.type("1850.50", delay=30); page.wait_for_timeout(200)
    check("Send an invoice: the VAT and the total are worked out as the amount is typed", "VAT €249.82" in d.inner_text() and "Total €2,100.32" in d.inner_text(), d.inner_text()[-300:])
    d.get_by_label("Choose a copy of the invoice from this device").set_input_files(FIX + "notes.txt"); page.wait_for_timeout(300)
    check("Send an invoice: a file that is not a PDF or a picture is refused in plain words", d.get_by_role("alert").inner_text().strip() != "")
    d.get_by_label("Choose a copy of the invoice from this device").set_input_files(FIX + "cert.pdf"); page.wait_for_timeout(400)
    check("Send an invoice: a PDF copy is attached", "cert.pdf" in d.inner_text() and d.get_by_role("alert").inner_text().strip() == "")
    page.screenshot(path=f"{OUT}/226-sub-send.png")
    d.get_by_role("button", name="Send invoice").click(); page.wait_for_timeout(400)
    sent = data(page, "(() => { const s = db.supplierInvoices.find(s => s.invoiceNo === 'CS-INV-9930'); return [s.party, s.via, s.jobRef, stage(s), s.subtotal, s.total, s.askedBy, s.copy && s.copy.name, s.allocations.map(a => a.projectId + ':' + a.category).join(), s.fileNo] })()")
    check("Send an invoice: it is on file for that site, with the copy, waiting for approval", sent[:9] == ["subcontractor", "portal", "C721", "approve", 1850.5, 2100.32, "Gearóid Flaherty", "cert.pdf", "pr-C721:labour"] and re.match(r"F-\d{4}", sent[9]), sent)
    row = view().get_by_label("Your invoices for C721").locator("tbody tr", has_text="CS-INV-9930")
    check("Send an invoice: the subcontractor sees it as received, with their copy to open, and is told who approves it", "Received" in row.inner_text() and "Waiting for approval" in row.inner_text() and row.get_by_role("link", name="cert.pdf").get_attribute("download") == "cert.pdf" and "It is with Róisín Garvey or the managing director to approve" in toast())
    go(page, "/admin/activity", "table")
    check("Send an invoice: the activity log has it under the subcontractor's own name", "Sent an invoice through the portal" in main.inner_text() and "Gearóid Flaherty" in main.inner_text())

    # ── The site manager approves for the sites they run
    as_role(page, "Site manager")
    go(page, "/invoicing")
    check("Site manager: still cannot open Invoicing", "/invoicing" not in page.url, page.url)
    go(page, "/projects/subcontractor-invoices")
    pj = page.get_by_role("navigation", name="Projects screens").first
    check("Site manager: Subcontractor invoices is in the Projects sidebar", pj.get_by_role("link", name="Subcontractor invoices").count() == 1)
    t = main.inner_text()
    check("Site manager: Eoin Brosnan sees what waits on the sites he runs, and no other site's", "C719 St Finian's Church" in t and "CS-INV-9921" in t and not re.search(r"C721|C722|C720|LRL-0412|CES-2231|CS-INV-9930", t) and "1 invoice from subcontractors waiting for approval on your sites, 1 of them yours to approve" in t, t[:400])
    page.get_by_role("tablist", name="Invoices shown").get_by_role("tab", name=re.compile("^Everything on these sites")).click(); page.wait_for_timeout(300)
    groups = [g.get_attribute("aria-label") for g in main.get_by_label("Subcontractor invoices for C719").locator("tbody").all()]
    check("Site manager: on a shared site each subcontractor's invoices sit under their own name", groups == ["Corrib Scaffolding at C719", "Kinvara Stone Carvers at C719"], groups)
    page.screenshot(path=f"{OUT}/227-site-manager.png")
    page.get_by_role("button", name="Approve CS-INV-9921").click(); page.wait_for_timeout(250)
    check("Site manager: Approve asks first", dlg().get_by_role("heading", name="Approve this invoice?").count() == 1 and "It goes into the job costs of C719 St Finian's Church" in dlg().inner_text())
    dlg().get_by_role("button", name="Confirm approval").click(); page.wait_for_timeout(300)
    row = main.locator("tbody tr", has_text="CS-INV-9921")
    check("Site manager: once confirmed it is approved in his name and with accounts to be paid", data(page, "(() => { const s = db.supplierInvoices.find(s => s.invoiceNo === 'CS-INV-9921'); return [stage(s), s.confirmedBy] })()") == ["pay", "Eoin Brosnan"] and "To be paid" in row.inner_text() and "Approved by Eoin Brosnan. Accounts pay it by" in row.inner_text() and row.get_by_role("button").count() == 0)

    # ── Accounts pay the subcontractor: told in the portal, and by email when ticked
    as_role(page, "Accounts")
    go(page, "/invoicing/to-pay", "table")
    page.get_by_role("tablist", name="Who is paid").get_by_role("tab", name=re.compile("^Subcontractors")).click(); page.wait_for_timeout(250)
    check("To be paid: narrowed to subcontractors", all("Subcontractor" in r.inner_text() for r in page.locator("tbody tr").all()) and "CS-INV-9921" in main.inner_text())
    mails = data(page, "db.mails.length")
    page.get_by_role("button", name="Mark CS-INV-9921 paid").click(); page.wait_for_timeout(250)
    tick = dlg().get_by_role("checkbox")
    check("Mark paid, subcontractor: the box says they are told in the portal, with a tick to email them as well", "Corrib Scaffolding sees it as paid in their portal as soon as you confirm" in dlg().inner_text() and tick.is_checked() and "Also email a remittance advice to accounts@corribscaffolding.example" in dlg().inner_text())
    dlg().get_by_role("button", name="Confirm paid").click(); page.wait_for_timeout(300)
    mail = data(page, "(() => { const s = db.supplierInvoices.find(s => s.invoiceNo === 'CS-INV-9921'); const m = db.mails.find(m => m.purchaseInvoiceId === s.id); return m ? [m.folder, m.subject, (m.to || '').includes('accounts@corribscaffolding.example')] : null })()")
    check("Mark paid, subcontractor: the remittance advice is filed under Email, Sent", data(page, "db.mails.length") == mails + 1 and mail == ["Sent", "Remittance advice: your invoice CS-INV-9921, C719 St Finian's Church", True] and "Gearóid Flaherty is told in the portal and by email" in toast(), mail)
    other = data(page, "db.supplierInvoices.filter(s => stage(s) === 'pay' && s.party === 'subcontractor')[0].invoiceNo")
    page.get_by_role("button", name=f"Mark {other} paid").click(); page.wait_for_timeout(250)
    dlg().get_by_role("checkbox").uncheck(); dlg().get_by_role("button", name="Confirm paid").click(); page.wait_for_timeout(300)
    check("Mark paid, subcontractor: without the tick nothing is emailed, the portal still says paid", data(page, "db.mails.length") == mails + 1 and data(page, f"stage(db.supplierInvoices.find(s => s.invoiceNo === '{other}'))") == "paid")
    as_role(page, "Managing director")
    go(page, "/inbox/sent")
    check("Email, Sent: the remittance advice is there to read", "Remittance advice: your invoice CS-INV-9921" in main.inner_text())
    go(page, "/portal/subcontractors?sub=sub-1&site=pr-C719")
    news = page.get_by_role("list", name="News on your invoices").inner_text()
    row = view().get_by_label("Your invoices for C719").locator("tbody tr", has_text="CS-INV-9921")
    check("Subcontractor portal: the payment is announced there at once, and the invoice reads Paid", "Paid: invoice CS-INV-9921 for C719." in news and "Paid" in row.inner_text() and "Paid on" in row.inner_text(), news[:300])
    page.screenshot(path=f"{OUT}/228-sub-paid.png")

    # ── A client is told too
    as_role(page, "Accounts")
    go(page, "/invoicing/invoiced", "table")
    no = data(page, "db.salesInvoices.find(i => i.status === 'Invoiced' && i.projectId === 'pr-C720').accountsNo")
    page.locator("tbody tr", has_text=no).get_by_role("button", name="Mark paid").click(); page.wait_for_timeout(250)
    check("Client invoice, Mark paid: the box names the client and offers a receipt by email", "Ardmullen Estate" in dlg().inner_text() and "sees it as paid in their portal as soon as you confirm" in dlg().inner_text() and dlg().get_by_role("checkbox").is_checked() and "Also email a receipt to" in dlg().inner_text())
    dlg().get_by_role("button", name="Confirm paid").click(); page.wait_for_timeout(300)
    receipt = data(page, f"(() => {{ const i = db.salesInvoices.find(i => i.accountsNo === '{no}'); const m = db.mails.find(m => m.salesInvoiceId === i.id && m.subject.startsWith('Payment received')); return [i.status, m ? m.folder : null, m ? m.subject : null] }})()")
    check("Client invoice, Mark paid: paid, with the receipt under Email, Sent", receipt == ["Paid", "Sent", f"Payment received: invoice {no}, C720 Ardmullen House"], receipt)
    as_role(page, "Client")
    page.wait_for_url("**/portal"); page.wait_for_timeout(300)
    news = page.get_by_role("list", name="News on your invoices")
    check("Client portal: the payment is announced at the top, with thanks", news.count() == 1 and f"Payment received: invoice {no} for Ardmullen House." in news.inner_text() and "Thank you" in news.inner_text(), news.inner_text() if news.count() else "")
    check("Client portal: a client sees only their own section", page.get_by_role("navigation", name="Portal screens").first.get_by_role("link").count() == 1 and "subcontractor" not in page.locator("body").inner_text().lower())
    page.goto(BASE + "/portal/subcontractors"); page.wait_for_timeout(500)
    check("Client portal: the subcontractors' section sends a client back to their own", page.url.endswith("/portal") and "Subcontractors by site" not in page.locator("body").inner_text(), page.url)
    page.screenshot(path=f"{OUT}/229-client-paid.png")
    as_role(page, "Managing director")
    go(page, "/admin/activity", "table")
    check("Activity log: sending for approval, approving, sending back, paying and the limit are all recorded", all(w in main.inner_text() for w in ["Sent a supplier invoice for approval", "Approved a supplier invoice into job costs", "Approved a subcontractor invoice into job costs", "Sent a supplier invoice back", "Marked a subcontractor invoice paid", "Changed what accounts may approve"]))

    # ── Dark and phone
    go(page, "/invoicing/subcontractor?inv=si-p4")
    page.get_by_role("button", name="Switch to dark mode").click(); page.wait_for_timeout(200)
    bg = page.get_by_label("The invoice as received").evaluate("e => getComputedStyle(e).backgroundColor")
    check("Dark mode: the invoice as received stays white paper", bg == "rgb(255, 255, 255)", bg)
    page.screenshot(path=f"{OUT}/230-sub-dark.png")
    go(page, "/portal/subcontractors")
    page.screenshot(path=f"{OUT}/231-sub-portal-dark.png")
    page.get_by_role("button", name="Switch to light mode").click()
    page.set_viewport_size({"width": 390, "height": 844})
    for path in ["/invoicing/invoiced?age=1", "/invoicing/supplier", "/invoicing/subcontractor", "/invoicing/approve", "/invoicing/to-pay", "/invoicing/export", "/invoicing/export?book=purchases", "/portal", "/portal/subcontractors", "/projects/subcontractor-invoices", "/dashboard"]:
        go(page, path)
        check(f"Phone width: page itself does not scroll sideways on {path}", not page.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth"))
    box = back.bounding_box()
    check("Phone width: Back is still at the far left of the top bar, and fits", back.is_visible() and box["x"] < 20 and box["width"] <= 44 and page.locator("header").first.evaluate("e => e.scrollWidth <= e.clientWidth"), box)
    page.screenshot(path=f"{OUT}/232-phone-bar.png")
    page.get_by_role("button", name="Search").click(); page.wait_for_timeout(250)
    check("Phone width: Back steps aside while the search is open, and returns when it closes", not back.is_visible())
    page.get_by_role("button", name="Cancel").click(); page.wait_for_timeout(250)
    check("Phone width: and comes back with Cancel", back.is_visible())
    go(page, "/portal/subcontractors")
    page.get_by_role("button", name="Send an invoice", exact=True).click(); page.wait_for_timeout(300)
    box = dlg().bounding_box()
    check("Phone width: the send form fits the screen, with its buttons in view", box["width"] <= 390 and dlg().get_by_role("button", name="Send invoice").is_visible(), box)
    page.screenshot(path=f"{OUT}/233-sub-send-phone.png")

errs = []
try:
    errs = run(steps)
except Exception as ex:
    print("STOPPED EARLY:", str(ex).split("\n")[0][:400])
for name, ok, detail in results:
    print(("PASS " if ok else "FAIL ") + name + ("" if ok else f"  [{detail[:300]}]"))
print("console problems:", errs)
print(f"{sum(1 for r in results if r[1])}/{len(results)} passed")
